import itertools

def count_inversions(p):
    inversions = 0
    for i in range(len(p)):
        for j in range(i + 1, len(p)):
            if p[i] > p[j]:
                inversions += 1
    return inversions

N = 5
permutations = list(itertools.permutations(range(1, N + 1)))

orbits = {}
for p in permutations:
    rotations = []
    for k in range(N):
        rotated_p = p[k:] + p[:k]
        rotations.append(rotated_p)

    canonical = min(rotations)

    if canonical not in orbits:
        orbits[canonical] = []
    orbits[canonical].append(p)

canonical_perms = list(orbits.keys())

max_distance_simple = 0
for canonical_p in canonical_perms:
    dist = count_inversions(canonical_p)
    max_distance_simple = max(max_distance_simple, dist)

print(f"N={N}. Number of orbits: {len(orbits)}")
print(f"Canonical permutations (first 3): {canonical_perms[:3]}")
print(f"Maximum distance from identity orbit: {max_distance_simple}")
